WITH event_rows AS (SELECT mktcode,tgtcode,bizdate,volume,MAX(volume) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) AS window_max FROM `newzl`.`hsj_stock_hq_basic`), event_keys AS (SELECT DISTINCT mktcode,tgtcode FROM event_rows WHERE bizdate IN (SELECT bizdate FROM `newzl`.`hsj_stock_hq_basic` GROUP BY bizdate ORDER BY bizdate DESC LIMIT 5) AND volume>=window_max), metric_keys AS (SELECT mktcode,tgtcode FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate IN (SELECT bizdate FROM `newzl`.`hsj_stock_hq_basic` GROUP BY bizdate ORDER BY bizdate DESC LIMIT 5) GROUP BY mktcode,tgtcode HAVING AVG(volume)>0) SELECT a.mktcode,a.tgtcode,a.bizdate FROM `newzl`.`hsj_stock_hq_basic` a JOIN event_keys e ON e.mktcode=a.mktcode AND e.tgtcode=a.tgtcode JOIN metric_keys m ON m.mktcode=a.mktcode AND m.tgtcode=a.tgtcode WHERE a.bizdate='2026-04-14';
